from pathlib import Path
import json, html, re
r=Path(__file__).resolve().parents[1]
b=json.loads((r/'content/conrad-personal-record.json').read_text())
p=r/'zh/publishing/index.html';s=p.read_text();path='/zh/publishing/conrad-personal-record/';url='https://overseasuk.com'+path;cover='https://overseasuk.com'+b['cover'];esc=html.escape
header=s[s.index('<body>')+6:s.index('<section class="page-hero">')];footer=s[s.index('<footer'):]
header=header.replace('https%3A%2F%2Foverseasuk.com%2Fzh%2Fpublishing%2F','https%3A%2F%2Foverseasuk.com%2Fzh%2Fpublishing%2Fconrad-personal-record%2F').replace('返回中文版主頁','出版目錄').replace('href="/zh/">出版目錄','href="/zh/publishing/">出版目錄')
seo={'@context':'https://schema.org','@type':'Book','name':b['title'],'alternateName':b['originalTitle'],'author':{'@type':'Person','name':b['author']},'translator':{'@type':'Person','name':b['translator']},'publisher':{'@type':'Organization','name':b['publisher']},'inLanguage':'zh-Hant','bookFormat':'https://schema.org/EBook','isbn':b['kindleIsbn'],'url':url,'image':cover}
head=f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>個人紀事｜康拉德著・蕭蓉譯｜海外書局</title><meta name="description" content="{esc(b['description'],quote=True)}"><link rel="canonical" href="{url}"><meta property="og:type" content="book"><meta property="og:title" content="個人紀事｜康拉德著・蕭蓉譯"><meta property="og:description" content="{esc(b['description'],quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{cover}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="{cover}"><link rel="stylesheet" href="/styles.css?v=times-new-roman-20260704b"><style>.book-layout{{display:grid;grid-template-columns:minmax(140px,230px) minmax(0,1fr);gap:2rem;align-items:start}}.book-cover{{width:100%;height:auto}}.book-details td,.book-details th{{text-align:left;padding:.6rem;vertical-align:top;overflow-wrap:anywhere}}@media(max-width:640px){{.book-layout{{grid-template-columns:1fr}}.book-cover{{max-width:210px}}}}</style><script type="application/ld+json">{json.dumps(seo,ensure_ascii=False)}</script></head><body>'''
rows=[('出版社',b['publisher']),('譯者',b['translator']),('審譯',b['reviewer']+'（列於版權頁）'),('初版年月','二〇二五年八月'),('Kindle ISBN',b['kindleIsbn']),('Amazon ASIN',b['asin']),('英國 Kindle 售價','£'+b['price'])]
body=f'''<section class="page-hero"><div class="band"><div class="eyebrow">海外書局 · 文學翻譯</div><h1>個人紀事</h1><p>A Personal Record</p><p>約瑟夫・康拉德著 · 蕭蓉譯</p></div></section><main class="band"><div class="book-layout"><img class="book-cover" src="{b['cover']}" alt="個人紀事繁體中文版新版封面，出版年月採小字排印" width="1024" height="1536"><div><h2>繁體中文電子版</h2><p>{esc(b['description'])}</p><table class="book-details">{''.join('<tr><th scope="row">'+k+'</th><td>'+esc(v)+'</td></tr>' for k,v in rows)}</table><h2>購書</h2><p>Kindle 電子版已於 Amazon 上架，英國售價 £4.99。實際售價與供應情況以 Amazon 頁面為準。</p><div class="actions"><a class="btn btn-primary" href="{b['amazon']}">Amazon Kindle／試讀</a></div><p>封面更新：出版年月縮小排印，保留紫灰菱格紋與中央雙線框。Amazon 封面顯示以平台更新進度為準。</p></div></div><h2>目錄</h2><ol>{''.join('<li>'+esc(x)+'</li>' for x in b['chapters'])}</ol><p><a href="/zh/publishing/">返回出版目錄</a></p></main>'''
out=r/path.strip('/')/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(head+header+body+footer)
card='<article id="conrad-personal-record"><b>文學翻譯</b><strong><a href="'+path+'">個人紀事</a></strong><p>約瑟夫・康拉德著，蕭蓉譯。海外書局繁體中文 Kindle 電子版已於 Amazon 上架，英國售價 £4.99；新版封面縮小出版年月。</p></article>'
if 'id="conrad-personal-record"' not in s:
 anchor='<article id="wells-autobiography">';assert anchor in s;p.write_text(s.replace(anchor,card+anchor,1))
p=r/'sitemap.xml';s=p.read_text()
if url not in s:p.write_text(s.replace('</urlset>',f'<url><loc>{url}</loc><lastmod>{b["updatedDate"]}</lastmod></url></urlset>'))
p=r/'zh/search/index.html';s=p.read_text();m=re.search(r'(<script type="application/json" id="search-data">)(.*?)(</script>)',s,re.S);assert m
a=json.loads(m.group(2));a=[x for x in a if x.get('url')!=path];a.insert(0,{'type':'書籍','title':'個人紀事｜康拉德著・蕭蓉譯','url':path,'desc':b['description']+' Amazon Kindle £4.99，ASIN '+b['asin']});p.write_text(s[:m.start(2)]+json.dumps(a,ensure_ascii=False)+s[m.end(2):])
print('Rendered Conrad book page, publishing index, search and sitemap')
